"""CuTe MoE LoRA apply kernels."""

from typing import NamedTuple

import torch

from kestrel_kernels.cubin_runtime import CubinFamily
from kestrel_kernels.fallback import ceil_div, is_cute_jit_enabled
from kestrel_kernels.moe.lora.fused_kernel import (
    LORA_MMA_BLOCK_M,
    MoeLoraFusedVariant,
    lora_mma_block_k,
    lora_mma_block_n,
    lora_mma_stages,
    lora_mma_warps,
)
from kestrel_kernels.moe.lora.route import lora_rank_bucket


class LoraSegRoute(NamedTuple):
    """(adapter, expert)-sorted routing for the tiled LoRA apply kernels."""

    sorted_ids: torch.Tensor       # (assignments,) int32 — sorted assignment ids
    cu_seqlens: torch.Tensor       # (weight_keys + 1,) int32 — exact key offsets
    block_row_start: torch.Tensor  # (max_blocks,) int32
    block_key: torch.Tensor        # (max_blocks,) int32
    n_blocks: torch.Tensor         # (1,) int32 — device block count
    rowscale_ones: torch.Tensor    # (assignments,) fp32 — tcgen expand up scale
    rowscale_tw: torch.Tensor      # (assignments,) fp32 — tcgen expand down scale
    use_tcgen_expand: bool = False


_family = CubinFamily("moe_lora")
_WARPS_PER_BLOCK = 8
_THREADS = _WARPS_PER_BLOCK * 32
_ENABLE_JIT = is_cute_jit_enabled()
if _ENABLE_JIT:
    from scripts.precompile import cubin_bundles as _cubin_bundles

def _device_arch(device: torch.device) -> str:
    from kestrel_kernels.arch import get_cuda_sm

    index = torch.cuda.current_device() if device.index is None else int(device.index)
    return f"sm{get_cuda_sm(index)}"


def _has_shipped_arch_variant(arch: str) -> bool:
    manifest = _family._load_manifest()
    if manifest is None:
        return False
    return any(
        _family._resolve_variant_entry(key, arch) is not None
        for key in manifest.get("variants", {})
    )


def supports_moe_lora(device: torch.device | str | None = None) -> bool:
    if device is None:
        if not torch.cuda.is_available():
            return False
        device = torch.device("cuda", torch.cuda.current_device())
    else:
        device = torch.device(device)
    if device.type != "cuda" or not torch.cuda.is_available():
        return False
    arch = _device_arch(device)
    if _has_shipped_arch_variant(arch):
        return True
    return _ENABLE_JIT


def _rank_limit(lora_a: torch.Tensor, active_lora_max_rank: int | None) -> int:
    storage_rank = int(lora_a.shape[1])
    if active_lora_max_rank is None:
        return storage_rank
    return min(storage_rank, max(0, int(active_lora_max_rank)))


def _ensure_variant(
    variant: MoeLoraFusedVariant, x: torch.Tensor, *, block_x: int | None = None
) -> str:
    if block_x is None:
        block_x = variant.warps_per_block * 32
    key = variant.variant_key
    device_index = int(x.device.index or 0)
    if _family.is_available(key) or (key, device_index) in _family._handles:
        return key
    if not _ENABLE_JIT:
        raise RuntimeError(
            f"No moe_lora cubin variant for {key}. The installed "
            "kestrel-kernels wheel does not include this precompiled kernel; "
            "upgrade or reinstall kestrel-kernels, or report the missing variant."
        )
    _cubin_bundles.jit_compile_and_install(
        family=_family,
        variant_key=key,
        compile_fn=_cubin_bundles._compile_moe_lora(variant),
        block_x=block_x,
        device_index=device_index,
    )
    return key


_ROUTE_THREADS = 1024
_ROUTE_SCATTER_THREADS = 256


def invoke_lora_route_topk(
    *,
    topk_ids: torch.Tensor,
    active_token_ids: torch.Tensor,
    active_lora_ids: torch.Tensor,
    active_lora_meta: torch.Tensor,
    topk_weights: torch.Tensor,
    sorted_ids: torch.Tensor,
    cu_seqlens: torch.Tensor,
    cursors: torch.Tensor,
    block_row_start: torch.Tensor,
    block_key: torch.Tensor,
    n_blocks: torch.Tensor,
    rowscale_ones: torch.Tensor,
    rowscale_tw: torch.Tensor,
    top_k: int,
    num_experts: int,
) -> None:
    """Sort active LoRA assignments by (adapter, expert), with exact offsets,
    a block_m block schedule for the tiled-MMA apply, and the per-sorted-row
    scale operands for the tcgen expand."""
    count_variant = MoeLoraFusedVariant(
        kind="route_count",
        in_dim=0,
        out_dim=0,
        top_k=int(top_k),
        num_experts=int(num_experts),
    )
    count_key = _ensure_variant(count_variant, topk_ids, block_x=_ROUTE_THREADS)
    _family.resolve_dispatch(
        topk_ids,
        variant_key=count_key,
        grid_x=1,
        grid_y=1,
        grid_z=1,
    )(
        topk_ids,
        active_token_ids,
        active_lora_ids,
        active_lora_meta,
        cu_seqlens,
        cursors,
        block_row_start,
        block_key,
        n_blocks,
    )
    scatter_variant = MoeLoraFusedVariant(
        kind="route_scatter",
        in_dim=0,
        out_dim=0,
        top_k=int(top_k),
        num_experts=int(num_experts),
        topk_weight_dtype=(
            "fp32" if topk_weights.dtype == torch.float32 else "bf16"
        ),
    )
    scatter_key = _ensure_variant(
        scatter_variant, topk_ids, block_x=_ROUTE_SCATTER_THREADS
    )
    _family.resolve_dispatch(
        topk_ids,
        variant_key=scatter_key,
        grid_x=max(
            1,
            ceil_div(
                ceil_div(int(sorted_ids.numel()), int(top_k)),
                _ROUTE_SCATTER_THREADS,
            ),
        ),
        grid_y=1,
        grid_z=1,
    )(
        topk_ids,
        active_token_ids,
        active_lora_ids,
        active_lora_meta,
        topk_weights,
        sorted_ids,
        cursors,
        rowscale_ones,
        rowscale_tw,
    )


def _mma_variant(
    kind: str,
    *,
    in_dim: int,
    out_dim: int,
    top_k: int,
    num_experts: int,
    x_per_assignment: bool = False,
    topk_weight_dtype: str = "bf16",
) -> MoeLoraFusedVariant:
    # The adapter rank bucket: shrink writes it (out), expand consumes it (in).
    rank = out_dim if kind == "mma_shrink" else in_dim
    return MoeLoraFusedVariant(
        kind=kind,
        in_dim=in_dim,
        out_dim=out_dim,
        top_k=top_k,
        num_experts=num_experts,
        warps_per_block=lora_mma_warps(kind, rank),
        x_per_assignment=x_per_assignment,
        topk_weight_dtype=topk_weight_dtype,
        block_m=LORA_MMA_BLOCK_M,
        block_n=lora_mma_block_n(kind, out_dim, rank),
        block_k=lora_mma_block_k(kind, rank),
        num_stages=lora_mma_stages(kind),
    )


def _invoke_shrink(
    *,
    x: torch.Tensor,
    lora_a: torch.Tensor,
    scratch: torch.Tensor,
    topk_ids: torch.Tensor,
    active_token_ids: torch.Tensor,
    active_lora_ids: torch.Tensor,
    active_lora_meta: torch.Tensor,
    lora_ranks: torch.Tensor,
    top_k: int,
    num_experts: int,
    x_per_assignment: bool,
    seg_route: "LoraSegRoute | None",
) -> None:
    rank_bucket = int(scratch.shape[1])
    if seg_route is not None:
        variant = _mma_variant(
            "mma_shrink",
            in_dim=int(x.shape[1]),
            out_dim=rank_bucket,
            top_k=int(top_k),
            num_experts=int(num_experts),
            x_per_assignment=bool(x_per_assignment),
        )
        key = _ensure_variant(variant, x)
        dummy_weights = torch.empty((0,), device=x.device, dtype=torch.bfloat16)
        _family.resolve_dispatch(
            x,
            variant_key=key,
            grid_x=ceil_div(rank_bucket, variant.block_n),
            grid_y=max(1, int(seg_route.block_row_start.numel())),
            grid_z=1,
        )(
            x,
            lora_a,
            scratch,
            dummy_weights,
            seg_route.sorted_ids,
            seg_route.cu_seqlens,
            seg_route.block_row_start,
            seg_route.block_key,
            seg_route.n_blocks,
            lora_ranks,
        )
        return
    variant = MoeLoraFusedVariant(
        kind="shrink",
        in_dim=int(x.shape[1]),
        out_dim=rank_bucket,
        top_k=int(top_k),
        num_experts=int(num_experts),
        warps_per_block=_WARPS_PER_BLOCK,
        x_per_assignment=bool(x_per_assignment),
    )
    key = _ensure_variant(variant, x)
    grid_x = max(1, ceil_div(int(scratch.shape[0]) * rank_bucket, _WARPS_PER_BLOCK))
    _family.resolve_dispatch(
        x,
        variant_key=key,
        grid_x=grid_x,
        grid_y=1,
        grid_z=1,
    )(
        x,
        lora_a,
        scratch,
        topk_ids,
        active_token_ids,
        active_lora_ids,
        active_lora_meta,
        lora_ranks,
    )


def _invoke_expand(
    *,
    scratch: torch.Tensor,
    lora_b: torch.Tensor,
    out2d: torch.Tensor,
    topk_weights: torch.Tensor | None,
    topk_ids: torch.Tensor,
    active_token_ids: torch.Tensor,
    active_lora_ids: torch.Tensor,
    active_lora_meta: torch.Tensor,
    lora_ranks: torch.Tensor,
    top_k: int,
    num_experts: int,
    mul_routed_weight: bool,
    seg_route: "LoraSegRoute | None",
) -> None:
    if mul_routed_weight:
        if topk_weights is None:
            raise ValueError("topk_weights is required for weighted LoRA expand")
        topk_weight_dtype = "fp32" if topk_weights.dtype == torch.float32 else "bf16"
    else:
        topk_weights = torch.empty(
            (0, int(top_k)), device=scratch.device, dtype=torch.bfloat16
        )
        topk_weight_dtype = "bf16"
    out_dim = int(out2d.shape[1])
    if seg_route is not None:
        # The tuned warp-MMA expand still wins at rank <= 16 (one k-step
        # covers the rank and its 128-wide tiles are issue-efficient);
        # tcgen takes over once the rank gives the MMA pipeline real depth.
        if (
            seg_route.use_tcgen_expand
            and int(scratch.shape[1]) >= 32
            and int(lora_b.shape[2]) == int(scratch.shape[1])
        ):
            from kestrel_kernels.cute_moe.dispatch import invoke_lora_expand_tcgen

            invoke_lora_expand_tcgen(
                scratch,
                lora_b,
                out2d,
                seg_route.sorted_ids,
                (
                    seg_route.rowscale_tw
                    if mul_routed_weight
                    else seg_route.rowscale_ones
                ),
                seg_route.cu_seqlens[: int(lora_b.shape[0]) + 1],
            )
            return
        variant = _mma_variant(
            "mma_expand_add_weighted" if mul_routed_weight else "mma_expand_add",
            in_dim=int(scratch.shape[1]),
            out_dim=out_dim,
            top_k=int(top_k),
            num_experts=int(num_experts),
            topk_weight_dtype=topk_weight_dtype,
        )
        key = _ensure_variant(variant, scratch)
        tw_flat = topk_weights.reshape(-1)
        _family.resolve_dispatch(
            scratch,
            variant_key=key,
            grid_x=ceil_div(out_dim, variant.block_n),
            grid_y=max(1, int(seg_route.block_row_start.numel())),
            grid_z=1,
        )(
            scratch,
            lora_b,
            out2d,
            tw_flat,
            seg_route.sorted_ids,
            seg_route.cu_seqlens,
            seg_route.block_row_start,
            seg_route.block_key,
            seg_route.n_blocks,
            lora_ranks,
        )
        return
    variant = MoeLoraFusedVariant(
        kind="expand_add_weighted" if mul_routed_weight else "expand_add",
        in_dim=int(scratch.shape[1]),
        out_dim=out_dim,
        top_k=int(top_k),
        num_experts=int(num_experts),
        warps_per_block=_WARPS_PER_BLOCK,
        topk_weight_dtype=topk_weight_dtype,
    )
    key = _ensure_variant(variant, scratch)
    _family.resolve_dispatch(
        scratch,
        variant_key=key,
        grid_x=max(1, int(scratch.shape[0])),
        grid_y=ceil_div(out_dim, _THREADS),
        grid_z=1,
    )(
        scratch,
        lora_b,
        out2d,
        topk_weights,
        topk_ids,
        active_token_ids,
        active_lora_ids,
        active_lora_meta,
        lora_ranks,
    )


def _validate_metadata(
    *,
    x: torch.Tensor,
    lora_a: torch.Tensor,
    lora_b: torch.Tensor,
) -> None:
    tensors = (
        x,
        lora_a,
        lora_b,
    )
    if any(t.device != x.device for t in tensors):
        raise ValueError("all MoE LoRA tensors must be on the same device")
    if x.device.type != "cuda":
        raise ValueError("CuTe MoE LoRA requires CUDA tensors")
    if x.dtype != torch.bfloat16:
        raise ValueError("CuTe MoE LoRA currently supports BF16 activations")
    if lora_a.dtype != torch.bfloat16 or lora_b.dtype != torch.bfloat16:
        raise ValueError("CuTe MoE LoRA currently supports BF16 LoRA weights")
    if not all(t.is_contiguous() for t in tensors):
        raise ValueError("CuTe MoE LoRA tensors must be contiguous")


def _validate_topk(
    top_k: int,
) -> None:
    top_k = int(top_k)
    if (
        top_k <= 0
        or (top_k & (top_k - 1)) != 0
    ):
        raise ValueError("CuTe MoE LoRA requires power-of-two top_k")


def _validate_scratch(
    *,
    scratch: torch.Tensor,
    x: torch.Tensor,
    rows: int,
    storage_rank: int,
) -> None:
    if scratch.device != x.device or scratch.dtype != torch.bfloat16:
        raise ValueError("scratch must be contiguous BF16 on the LoRA device")
    if (
        scratch.ndim != 2
        or int(scratch.shape[0]) != rows
        or int(scratch.shape[1]) < storage_rank
    ):
        raise ValueError("scratch must have shape [tokens * top_k, storage_lora_rank]")


def _validate_routing_inputs(
    *,
    topk_ids: torch.Tensor,
    active_token_ids: torch.Tensor,
    active_lora_ids: torch.Tensor,
    active_lora_meta: torch.Tensor,
    device: torch.device,
) -> None:
    tensors = (topk_ids, active_token_ids, active_lora_ids, active_lora_meta)
    if any(t.device != device for t in tensors):
        raise ValueError("LoRA routing tensors must be on the LoRA device")
    if any(t.dtype != torch.int32 for t in tensors):
        raise ValueError("LoRA routing tensors must use int32")
    if topk_ids.ndim != 2:
        raise ValueError("topk_ids must be 2D [tokens, top_k]")
    if (
        active_token_ids.ndim != 1
        or active_lora_ids.ndim != 1
        or active_lora_meta.ndim != 1
    ):
        raise ValueError("LoRA activation metadata tensors must be 1D")
    if not all(t.is_contiguous() for t in tensors):
        raise ValueError("LoRA routing tensors must be contiguous")


def _validate_seg_route(
    *,
    seg_route: "LoraSegRoute | None",
    num_experts: int,
    assignments: int,
    device: torch.device,
) -> None:
    if seg_route is None:
        return
    if int(seg_route.n_blocks.numel()) < 1 or int(
        seg_route.block_row_start.numel()
    ) != int(seg_route.block_key.numel()):
        raise ValueError("seg_route block schedule tensors are inconsistent")
    for t in (
        seg_route.sorted_ids,
        seg_route.cu_seqlens,
        seg_route.block_row_start,
        seg_route.block_key,
        seg_route.n_blocks,
    ):
        if t.device != device or t.dtype != torch.int32 or t.ndim != 1 or not t.is_contiguous():
            raise ValueError("seg_route tensors must be contiguous int32 1D on the LoRA device")
    if int(seg_route.sorted_ids.numel()) < assignments:
        raise ValueError("seg_route sorted_token_ids must cover all assignments")
    if int(seg_route.cu_seqlens.numel()) < num_experts + 1:
        raise ValueError(
            "seg_route cu_seqlens must cover adapter_weights * num_experts + 1 entries"
        )


def _ranks_tensor(
    x: torch.Tensor,
    lora_ranks: torch.Tensor | None,
    *,
    lora_a: torch.Tensor,
    num_experts: int,
) -> torch.Tensor:
    if lora_ranks is None:
        raise ValueError("lora_ranks is required for routed MoE LoRA")
    if (
        lora_ranks.device != x.device
        or lora_ranks.dtype != torch.int32
        or lora_ranks.ndim != 1
        or not lora_ranks.is_contiguous()
    ):
        raise ValueError("lora_ranks must be a contiguous int32 1D tensor on the LoRA device")
    weight_loras = int(lora_a.shape[0]) // int(num_experts)
    if int(lora_ranks.shape[0]) < weight_loras:
        raise ValueError("lora_ranks must cover every adapter in the LoRA weights")
    return lora_ranks


@torch.inference_mode()
def apply_moe_lora_up(
    *,
    x: torch.Tensor,
    base_up: torch.Tensor,
    lora_a: torch.Tensor,
    lora_b: torch.Tensor,
    topk_ids: torch.Tensor,
    active_token_ids: torch.Tensor,
    active_lora_ids: torch.Tensor,
    active_lora_meta: torch.Tensor,
    num_experts: int,
    scratch: torch.Tensor,
    lora_ranks: torch.Tensor | None = None,
    active_lora_max_rank: int | None = None,
    seg_route: "LoraSegRoute | None" = None,
) -> None:
    _validate_metadata(
        x=x,
        lora_a=lora_a,
        lora_b=lora_b,
    )
    if base_up.device != x.device:
        raise ValueError("base_up must be on the LoRA device")
    if base_up.dtype != torch.bfloat16:
        raise ValueError("base_up must be BF16")
    if base_up.ndim != 3:
        raise ValueError("base_up must have shape [tokens, top_k, 2 * intermediate]")
    if not base_up.is_contiguous():
        raise ValueError("base_up must be contiguous")
    if x.ndim != 2 or int(x.shape[0]) != int(base_up.shape[0]):
        raise ValueError("x must have shape [tokens, hidden] matching base_up")
    top_k = int(base_up.shape[1])
    output_dim = int(base_up.shape[2])
    if output_dim % 2 != 0:
        raise ValueError("base_up output dimension must be even")
    if int(lora_b.shape[1]) != output_dim:
        raise ValueError("lora_b must have shape [adapter_expert_rows, 2 * intermediate, rank]")
    _validate_routing_inputs(
        topk_ids=topk_ids,
        active_token_ids=active_token_ids,
        active_lora_ids=active_lora_ids,
        active_lora_meta=active_lora_meta,
        device=x.device,
    )

    _validate_topk(top_k)
    rank = _rank_limit(lora_a, active_lora_max_rank)
    rank_bucket = lora_rank_bucket(rank)
    if int(lora_b.shape[2]) < rank:
        raise ValueError("lora_b rank dimension must cover the active LoRA rank")
    _validate_scratch(
        scratch=scratch,
        x=x,
        rows=int(base_up.shape[0]) * int(base_up.shape[1]),
        storage_rank=rank_bucket,
    )
    if rank > 0:
        ranks = _ranks_tensor(x, lora_ranks, lora_a=lora_a, num_experts=num_experts)
        _validate_seg_route(
            seg_route=seg_route,
            num_experts=num_experts,
            assignments=int(base_up.shape[0]) * top_k,
            device=x.device,
        )
        scratch_rank = scratch[:, :rank_bucket]
        _invoke_shrink(
            x=x,
            lora_a=lora_a,
            scratch=scratch_rank,
            topk_ids=topk_ids,
            active_token_ids=active_token_ids,
            active_lora_ids=active_lora_ids,
            active_lora_meta=active_lora_meta,
            lora_ranks=ranks,
            top_k=top_k,
            num_experts=num_experts,
            x_per_assignment=False,
            seg_route=seg_route,
        )
        _invoke_expand(
            scratch=scratch_rank,
            lora_b=lora_b,
            out2d=base_up.view(-1, output_dim),
            topk_weights=None,
            topk_ids=topk_ids,
            active_token_ids=active_token_ids,
            active_lora_ids=active_lora_ids,
            active_lora_meta=active_lora_meta,
            lora_ranks=ranks,
            top_k=top_k,
            num_experts=num_experts,
            mul_routed_weight=False,
            seg_route=seg_route,
        )


@torch.inference_mode()
def apply_moe_lora_up_gelu(
    *,
    x: torch.Tensor,
    base_up: torch.Tensor,
    activation: torch.Tensor,
    lora_a: torch.Tensor,
    lora_b: torch.Tensor,
    topk_ids: torch.Tensor,
    active_token_ids: torch.Tensor,
    active_lora_ids: torch.Tensor,
    active_lora_meta: torch.Tensor,
    num_experts: int,
    scratch: torch.Tensor,
    lora_ranks: torch.Tensor | None = None,
    active_lora_max_rank: int | None = None,
    seg_route: "LoraSegRoute | None" = None,
    interleaved: bool = False,
) -> None:
    # interleaved=True: base_up (and the pre-interleaved lora_b it is RMW'd
    # with) use the 8-row gate/up interleave, so the gated-GELU reads that
    # ordering. The expand itself is column-independent, so it needs no remap
    # here — only the activation read below changes.
    if activation.device != x.device:
        raise ValueError("activation must be on the LoRA device")
    if activation.dtype != torch.bfloat16:
        raise ValueError("activation must be BF16")
    if not activation.is_contiguous():
        raise ValueError("activation must be contiguous")
    if base_up.ndim != 3:
        raise ValueError("base_up must have shape [tokens, top_k, 2 * intermediate]")
    output_dim = int(base_up.shape[2])
    if output_dim % 2 != 0:
        raise ValueError("base_up output dimension must be even")
    intermediate = output_dim // 2
    if tuple(activation.shape) != (int(base_up.shape[0]) * int(base_up.shape[1]), intermediate):
        raise ValueError("activation must have shape [tokens * top_k, intermediate]")
    apply_moe_lora_up(
        x=x,
        base_up=base_up,
        lora_a=lora_a,
        lora_b=lora_b,
        topk_ids=topk_ids,
        active_token_ids=active_token_ids,
        active_lora_ids=active_lora_ids,
        active_lora_meta=active_lora_meta,
        num_experts=num_experts,
        scratch=scratch,
        lora_ranks=lora_ranks,
        active_lora_max_rank=active_lora_max_rank,
        seg_route=seg_route,
    )
    from kestrel_kernels.gelu_residual import gelu_residual_cute

    gelu_residual_cute(
        activation, base_up.view(-1, output_dim), interleaved=interleaved
    )


@torch.inference_mode()
def apply_moe_lora_down_sum(
    *,
    x: torch.Tensor,
    topk_weights: torch.Tensor,
    base_down: torch.Tensor,
    output: torch.Tensor,
    lora_a: torch.Tensor,
    lora_b: torch.Tensor,
    topk_ids: torch.Tensor,
    active_token_ids: torch.Tensor,
    active_lora_ids: torch.Tensor,
    active_lora_meta: torch.Tensor,
    num_experts: int,
    scratch: torch.Tensor,
    lora_ranks: torch.Tensor | None = None,
    active_lora_max_rank: int | None = None,
    seg_route: "LoraSegRoute | None" = None,
) -> None:
    _validate_metadata(
        x=x,
        lora_a=lora_a,
        lora_b=lora_b,
    )
    tensors = (topk_weights, base_down, output)
    if any(t.device != x.device for t in tensors):
        raise ValueError("topk_weights, base_down, and output must be on the LoRA device")
    if topk_weights.dtype not in (torch.bfloat16, torch.float32):
        raise ValueError("topk_weights must be BF16 or FP32")
    if base_down.dtype != torch.bfloat16 or output.dtype != torch.bfloat16:
        raise ValueError("base_down and output must be BF16")
    if base_down.ndim != 3:
        raise ValueError("base_down must have shape [tokens, top_k, hidden]")
    if x.ndim != 2 or int(x.shape[0]) != int(base_down.shape[0]) * int(base_down.shape[1]):
        raise ValueError("x must have shape [tokens * top_k, hidden] matching base_down")
    if output.ndim != 2 or tuple(output.shape) != (int(base_down.shape[0]), int(base_down.shape[2])):
        raise ValueError("output must have shape [tokens, hidden]")
    expected_topk_shape = tuple(base_down.shape[:2])
    if topk_weights.ndim != 2 or tuple(topk_weights.shape) != expected_topk_shape:
        raise ValueError("topk_weights must have shape [tokens, top_k] matching base_down")
    if not all(t.is_contiguous() for t in tensors):
        raise ValueError("topk_weights, base_down, and output must be contiguous")

    top_k = int(base_down.shape[1])
    _validate_topk(top_k)
    output_dim = int(base_down.shape[2])
    rank = _rank_limit(lora_a, active_lora_max_rank)
    rank_bucket = lora_rank_bucket(rank)
    if int(lora_b.shape[1]) != output_dim or int(lora_b.shape[2]) < rank:
        raise ValueError("lora_b must have shape [adapter_expert_rows, hidden, rank]")
    _validate_routing_inputs(
        topk_ids=topk_ids,
        active_token_ids=active_token_ids,
        active_lora_ids=active_lora_ids,
        active_lora_meta=active_lora_meta,
        device=x.device,
    )
    _validate_scratch(
        scratch=scratch,
        x=x,
        rows=int(base_down.shape[0]) * int(base_down.shape[1]),
        storage_rank=rank_bucket,
    )
    if rank > 0:
        ranks = _ranks_tensor(x, lora_ranks, lora_a=lora_a, num_experts=num_experts)
        _validate_seg_route(
            seg_route=seg_route,
            num_experts=num_experts,
            assignments=int(base_down.shape[0]) * top_k,
            device=x.device,
        )
        scratch_rank = scratch[:, :rank_bucket]
        _invoke_shrink(
            x=x,
            lora_a=lora_a,
            scratch=scratch_rank,
            topk_ids=topk_ids,
            active_token_ids=active_token_ids,
            active_lora_ids=active_lora_ids,
            active_lora_meta=active_lora_meta,
            lora_ranks=ranks,
            top_k=top_k,
            num_experts=num_experts,
            x_per_assignment=True,
            seg_route=seg_route,
        )
        _invoke_expand(
            scratch=scratch_rank,
            lora_b=lora_b,
            out2d=base_down.view(-1, output_dim),
            topk_weights=topk_weights,
            topk_ids=topk_ids,
            active_token_ids=active_token_ids,
            active_lora_ids=active_lora_ids,
            active_lora_meta=active_lora_meta,
            lora_ranks=ranks,
            top_k=top_k,
            num_experts=num_experts,
            mul_routed_weight=True,
            seg_route=seg_route,
        )
    from kestrel_kernels.moe_sum_ops import moe_sum

    moe_sum(base_down, output)


__all__ = [
    "apply_moe_lora_down_sum",
    "apply_moe_lora_up",
    "apply_moe_lora_up_gelu",
    "supports_moe_lora",
]
